@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject BlazorNotifications.Services.NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorNotifications.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    protected override void OnInitialized()
    {
        // Runs during SSR and again when the component becomes interactive.
        // We only load data the first time (SSR); the interactive activation
        // sees the list is already populated via PersistentComponentState-free
        // approach: OnInitialized runs in both modes, but we guard the poll
        // start in OnAfterRenderAsync.
        _notifications = NotificationSvc.GetAll();
        _lastCheck = DateTime.UtcNow;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires when the component is interactive
            // (never during static SSR), so this is the safe place to
            // start the polling loop.

            // Re-sync the list so we don't lose what SSR rendered, but
            // also pick up anything that arrived between SSR and going live.
            var fresh = NotificationSvc.GetSince(_lastCheck);
            if (fresh.Count > 0)
            {
                _notifications.InsertRange(0, fresh);
                _lastCheck = DateTime.UtcNow;
                StateHasChanged();
            }

            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        // Simulate external notifications arriving periodically
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(5));

        while (await timer.WaitForNextTickAsync(ct))
        {
            // Simulate a new notification arriving roughly every other poll
            if (Random.Shared.Next(2) == 0)
            {
                NotificationSvc.SimulateIncoming();
            }

            var newer = NotificationSvc.GetSince(_lastCheck);
            if (newer.Count > 0)
            {
                _notifications.InsertRange(0, newer);
                _lastCheck = DateTime.UtcNow;
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

